import { build } from 'vite'
import { readFileSync, writeFileSync } from 'node:fs'
const result = await build({
  configFile: false,
  publicDir: false,
  logLevel: 'silent',
  build: {
    write: false,
    minify: false,
    target: 'es2022',
    lib: {
      entry: 'src/features/arcade/tower-defense-replay.ts',
      formats: ['es'],
      fileName: 'tower-defense-replay',
    },
  },
})
const output = Array.isArray(result) ? result[0] : result,
  code =
    '// Generated by npm run tower-defense:engine. Do not edit.\n' +
    output.output.find((chunk) => chunk.type === 'chunk').code
const file = 'supabase/functions/_shared/tower-defense-replay.js'
if (process.argv.includes('--check')) {
  if (readFileSync(file, 'utf8').replaceAll('\r\n', '\n') !== code)
    throw Error('Tower defense server engine is stale; run npm run tower-defense:engine')
} else writeFileSync(file, code)
